function model = generated_build_thermal_rectangle_surrogate()
%GENERATED_BUILD_THERMAL_RECTANGLE_SURROGATE Build a constrained COMSOL starter model.
% Generated by comsol_training_small_model.
%
% Run inside COMSOL with MATLAB:
%   model = generated_build_thermal_rectangle_surrogate;

import com.comsol.model.*
import com.comsol.model.util.*

model = ModelUtil.create('Model');
model.label('thermal_rectangle_surrogate.mph');

model.param.set('L', '0.05[m]', 'Rectangle length');
model.param.set('W', '0.02[m]', 'Rectangle width');
model.param.set('k', '16.0[W/(m*K)]', 'Thermal conductivity');
model.param.set('rho', '7800.0[kg/m^3]', 'Density');
model.param.set('Cp', '500.0[J/(kg*K)]', 'Heat capacity');
model.param.set('heat_flux', '8000.0[W/m^2]', 'Boundary heat flux');
model.param.set('h', '35.0[W/(m^2*K)]', 'Convective heat transfer coefficient');
model.param.set('Text', '293.15[K]', 'External temperature');
model.param.set('hmax', '0.004[m]', 'Maximum mesh size');

% Sweep candidate k: [5.0 10.0 16.0 25.0 50.0]
% Sweep candidate heat_flux: [2000.0 5000.0 8000.0 12000.0]
% Sweep candidate h: [10.0 20.0 35.0 60.0]
% Sweep candidate L: [0.02 0.05 0.08]

model.component.create('comp1', true);
model.component('comp1').geom.create('geom1', 2);
model.component('comp1').geom('geom1').lengthUnit('m');
model.component('comp1').geom('geom1').create('r1', 'Rectangle');
model.component('comp1').geom('geom1').feature('r1').set('size', {'L' 'W'});
model.component('comp1').geom('geom1').run;

model.component('comp1').material.create('mat1', 'Common');
model.component('comp1').material('mat1').label('Constrained solid');
model.component('comp1').material('mat1').propertyGroup('def').set('thermalconductivity', 'k');
model.component('comp1').material('mat1').propertyGroup('def').set('density', 'rho');
model.component('comp1').material('mat1').propertyGroup('def').set('heatcapacity', 'Cp');

model.component('comp1').physics.create('ht', 'HeatTransferInSolids', 'geom1');
% Boundary selections are placeholders. Inspect geometry boundary numbers before production runs.
model.component('comp1').physics('ht').create('hf1', 'HeatFluxBoundary', 1);
model.component('comp1').physics('ht').feature('hf1').selection.set([1]);
model.component('comp1').physics('ht').feature('hf1').set('q0', 'heat_flux');
model.component('comp1').physics('ht').create('hf2', 'HeatFluxBoundary', 1);
model.component('comp1').physics('ht').feature('hf2').selection.set([2 3 4]);
model.component('comp1').physics('ht').feature('hf2').set('HeatFluxType', 'ConvectiveHeatFlux');
model.component('comp1').physics('ht').feature('hf2').set('h', 'h');
model.component('comp1').physics('ht').feature('hf2').set('Text', 'Text');

model.component('comp1').mesh.create('mesh1');
model.component('comp1').mesh('mesh1').create('size1', 'Size');
model.component('comp1').mesh('mesh1').feature('size1').set('custom', true);
model.component('comp1').mesh('mesh1').feature('size1').set('hmax', 'hmax');
model.component('comp1').mesh('mesh1').create('ftri1', 'FreeTri');
model.component('comp1').mesh('mesh1').run;

model.component('comp1').cpl.create('maxop1', 'Maximum');
model.component('comp1').cpl('maxop1').selection.all;
model.component('comp1').cpl.create('aveop1', 'Average');
model.component('comp1').cpl('aveop1').selection.all;

model.study.create('std1');
model.study('std1').create('stat', 'Stationary');
model.study('std1').createAutoSequences('all');
model.study('std1').run;

model.result.numerical.create('Tmax', 'EvalGlobal');
model.result.numerical('Tmax').set('expr', 'maxop1(T)');
model.result.numerical.create('Tavg', 'EvalGlobal');
model.result.numerical('Tavg').set('expr', 'aveop1(T)');

model.save(fullfile(pwd, [model.label]));
end
